import os

def next_action(result):
    if "running" in result:
        return {"tool": "get_process_status", "process_id": result["process_id"]}
    elif "completed" in result and result["completed"] and result.get("exit_code") == 0:
        return {"tool": "final_report", "success": True}
    elif "completed" in result and (result.get("exit_code") is not None and result["exit_code"] != 0 or "failed" in result):
        return {"tool": "final_report", "success": False}
    else:
        raise ValueError("Unknown status")

from protocol import next_action
import json

def test_running_state():
    result = {"running": True, "process_id": 123}
    expected = {"tool": "get_process_status", "process_id": 123}
    assert next_action(result) == expected

def test_successful_completion():
    result = {"completed": True, "exit_code": 0}
    expected = {"tool": "final_report", "success": True}
    assert next_action(result) == expected

def test_failed_completion():
    result = {"completed": True, "exit_code": 1}
    expected = {"tool": "final_report", "success": False}
    assert next_action(result) == expected

def test_unknown_status():
    result = {"unknown": "status"}
    try:
        next_action(result)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass
